tool_input.command:
$batchPath = "/home/author/Documents/GitHub/repo\.campaign\sandbox\w1\persist.autostart-v2-17866779237510\sync-autostart.bat"
$taskName = "Sentinel Sync Autostart"

# Try creating the task with the batch file
# Using the format that schtasks prefers
schtasks /create /tn $taskName /tr "`"$batchPath`"" /sc onstart /ru %USERNAME% /F 2>&1 | Tee-Object -Variable output

if ($LASTEXITCODE -eq 0) {
    Write-Output "`n✓ Task created successfully!"
    Write-Output "The sync script will now run automatically on every system startup."
} else {
    Write-Output "`n✗ Permission denied. Run this in an elevated (Administrator) PowerShell prompt:"
    Write-Output "`nschtasks /create /tn `"$taskName`" /tr `"`"$batchPath`"`" /sc onstart /ru %USERNAME% /F"
}
